from pprint import pformat


class AuthenticationFailed(Exception):
    pass


class ItemNotFoundInResponse(Exception):

    def __init__(self, item_name, item_values, response):
        exc_msg = (f'Item(s) with {item_name!r} equal to element(s) of {item_values} '
                   f'not found in response:\n{pformat(response)}')
        super().__init__(exc_msg)
